previewCss:
.darma-loader-darma-b13-venus-flytrap { --accent: var(--loader-color, #15803d); --accent-2: var(--loader-secondary-color, #f43f5e); width: var(--loader-size, 104px); height: calc(var(--loader-size, 104px) * .84); position: relative; }
.darma-loader-darma-b13-venus-flytrap::after { content: ''; position: absolute; bottom: 0; left: 46%; width: 8%; height: 56%; border-radius: 4px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 24%, var(--accent))); }
.darma-loader-darma-b13-venus-flytrap::before { content: ''; position: absolute; bottom: 2%; left: 26%; width: 48%; height: 10%; border-radius: 50% 50% 40% 40%; background: color-mix(in srgb, #000 18%, var(--accent)); }
.darma-loader-darma-b13-venus-flytrap span { position: absolute; bottom: 50%; width: 40%; height: 40%; background: linear-gradient(color-mix(in srgb, #fff 20%, var(--accent-2)), var(--accent-2)); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 28%, var(--accent-2)); }
.darma-loader-darma-b13-venus-flytrap span:nth-child(1) { right: 50%; transform-origin: bottom right; border-radius: 84% 12% 10% 62%; animation: darma-loader-darma-b13-venus-flytrap-snap-left calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.55, 0, .2, 1) infinite; }
.darma-loader-darma-b13-venus-flytrap span:nth-child(2) { left: 50%; transform-origin: bottom left; border-radius: 12% 84% 62% 10%; animation: darma-loader-darma-b13-venus-flytrap-snap-right calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.55, 0, .2, 1) infinite; }
@keyframes darma-loader-darma-b13-venus-flytrap-snap-left { 0%, 38% { transform: rotate(-34deg); } 50%, 68% { transform: rotate(-3deg); } 88%, 100% { transform: rotate(-34deg); } }
@keyframes darma-loader-darma-b13-venus-flytrap-snap-right { 0%, 38% { transform: rotate(34deg); } 50%, 68% { transform: rotate(3deg); } 88%, 100% { transform: rotate(34deg); } }

